#include <iostream>
#include <vector>
using namespace std;

int main() {   //@ @layout open:visualizer
    int n = 3;   //@ @tts [next] 先決定要放幾個數字，現在只開程式追蹤表
    vector<int> v;   //@ @tts [next] 接下來要看容器，所以換成容器面板 @layout open:container close:visualizer
    for (int i = 1; i <= n; i++) {   //@ @tts [next] 開始放數字 | @2 [next] 下一個
        v.push_back(i * i);   //@ @guide {v} @tts [next] 放進第 {i} 個平方數
    }
    cout << v.size() << endl;   //@ @guide {v} @tts [next] 全部放好了
    return 0;   //@ @tts [continue] 程式結束
}
